715	function ConnectorBody({
716		ownerSlug,
717		organizationId,
718		isWorkspaceLoading,
719		connectorKey,
720	}: {
721		ownerSlug: string;
722		organizationId: string | null;
723		isWorkspaceLoading: boolean;
724		connectorKey: string;
725	}) {
726		// Resolve against the full installable catalog (not just installed defs) so
727		// a bundled-but-not-yet-installed connector — e.g. the managed-chat Slack
728		// connector reached from the catalog card — still resolves and renders its
729		// install affordance instead of the "not installed, details unavailable"
730		// dead end.
731		const { data: connectorDefs = [], isLoading: isDefsLoading } =
732			useInstallableConnectorCatalog(organizationId ?? "");
733		const {
734			data: connections = [],
735			isLoading: isConnectionsLoading,
736			refetch: refetchConnections,
737		} = useConnections(organizationId ?? "", { connectorKey });
738		const connector = useMemo(
739			() => connectorDefs.find((def) => def.key === connectorKey),
740			[connectorDefs, connectorKey],
741		);
742	
743		// The connection's stored connector_name is the fallback display when no
744		// definition is installed (orphaned connector, or a connection created
745		// outside the install flow) — same def-or-fallback resolution the Connectors
746		// list uses, so the page never dead-ends on a missing definition.
747		const display = useMemo(
748			() =>
749				resolveConnectorDisplay(connectorKey, connectorDefs, {
750					name: connections[0]?.connector_name ?? connectorKey,
751				}),
752			[connectorKey, connectorDefs, connections],
753		);
754	
755		if (isWorkspaceLoading || isDefsLoading) {
756			// Skeleton mirrors `<ConnectorInfo>` shape (connector-panels.tsx:303):
757			// icon + name row, description card, auth + feeds + actions panels.
758			// Each panel reserves its loaded footprint so the page doesn't
759			// shift when data arrives.
760			return (
761				<div>
762					<div className="w-full max-w-3xl space-y-4">
763						<div className="flex items-center gap-2">
764							<Skeleton className="h-6 w-6 rounded" />
765							<Skeleton className="h-5 w-40" />
766						</div>
767						<Skeleton className="h-16 w-full rounded-lg" />
768						<Skeleton className="h-24 w-full rounded-lg" />
769						<Skeleton className="h-32 w-full rounded-lg" />
770					</div>
771				</div>
772			);
773		}
774	
775		const hero = connector ? (
776			<ConnectorHero connector={connector} ownerSlug={ownerSlug} />
777		) : (
778			<div className="space-y-3">
779				<ConnectorDisplay
780					connector={display}
781					showDescription={false}
782					className="gap-2"
783				/>
784				<p className="text-sm text-muted-foreground">
785					This connector isn't installed in this workspace, so its details aren't
786					available.
787					{connections.length > 0
788						? " Existing connections still appear below."
789						: ""}
790				</p>
791			</div>
792		);
793	
794		return (
795			<div className="flex flex-1 flex-col">
796				{connector && organizationId ? (
797					<ConnectorDetailShell
798						hero={hero}
799						connector={connector}
800						organizationId={organizationId}
801						ownerSlug={ownerSlug}
802						connectorKey={connectorKey}
803						connections={connections}
804						isLoading={isConnectionsLoading}
805						refetchConnections={refetchConnections}
806					/>
807				) : (
808					<div className="w-full max-w-3xl space-y-6">
809						{hero}
810						<ConnectionsForConnector
811							ownerSlug={ownerSlug}
812							connectorKey={connectorKey}
813							connections={connections}
814							isLoading={isConnectionsLoading}
815						/>
816					</div>
817				)}
818			</div>
819		);
820	}
821	
