function ConnectorBody({
	ownerSlug,
	organizationId,
	isWorkspaceLoading,
	connectorKey,
}: {
	ownerSlug: string;
	organizationId: string | null;
	isWorkspaceLoading: boolean;
	connectorKey: string;
}) {
	// Resolve against the full installable catalog (not just installed defs) so
	// a bundled-but-not-yet-installed connector — e.g. the managed-chat Slack
	// connector reached from the catalog card — still resolves and renders its
	// install affordance instead of the "not installed, details unavailable"
	// dead end.
	const { data: connectorDefs = [], isLoading: isDefsLoading } =
		useInstallableConnectorCatalog(organizationId ?? "");
	const {
		data: connections = [],
		isLoading: isConnectionsLoading,
		refetch: refetchConnections,
	} = useConnections(organizationId ?? "", { connectorKey });
	const connector = useMemo(
		() => connectorDefs.find((def) => def.key === connectorKey),
		[connectorDefs, connectorKey],
	);

	// The connection's stored connector_name is the fallback display when no
	// definition is installed (orphaned connector, or a connection created
	// outside the install flow) — same def-or-fallback resolution the Connectors
	// list uses, so the page never dead-ends on a missing definition.
	const display = useMemo(
		() =>
			resolveConnectorDisplay(connectorKey, connectorDefs, {
				name: connections[0]?.connector_name ?? connectorKey,
			}),
		[connectorKey, connectorDefs, connections],
	);

	if (isWorkspaceLoading || isDefsLoading) {
		// Skeleton mirrors `<ConnectorInfo>` shape (connector-panels.tsx:303):
		// icon + name row, description card, auth + feeds + actions panels.
		// Each panel reserves its loaded footprint so the page doesn't
		// shift when data arrives.
		return (
			<div>
				<div className="w-full max-w-3xl space-y-4">
					<div className="flex items-center gap-2">
						<Skeleton className="h-6 w-6 rounded" />
						<Skeleton className="h-5 w-40" />
					</div>
					<Skeleton className="h-16 w-full rounded-lg" />
					<Skeleton className="h-24 w-full rounded-lg" />
					<Skeleton className="h-32 w-full rounded-lg" />
				</div>
			</div>
		);
	}

	const hero = connector ? (
		<ConnectorHero connector={connector} ownerSlug={ownerSlug} />
	) : (
		<div className="space-y-3">
			<ConnectorDisplay
				connector={display}
				showDescription={false}
				className="gap-2"
			/>
			<p className="text-sm text-muted-foreground">
				This connector isn't installed in this workspace, so its details aren't
				available.
				{connections.length > 0
					? " Existing connections still appear below."
					: ""}
			</p>
		</div>
	);

	return (
		<div className="flex flex-1 flex-col">
			{connector && organizationId ? (
				<ConnectorDetailShell
					hero={hero}
					connector={connector}
					organizationId={organizationId}
					ownerSlug={ownerSlug}
					connectorKey={connectorKey}
					connections={connections}
					isLoading={isConnectionsLoading}
					refetchConnections={refetchConnections}
				/>
			) : (
				<div className="w-full max-w-3xl space-y-6">
					{hero}
					<ConnectionsForConnector
						ownerSlug={ownerSlug}
						connectorKey={connectorKey}
						connections={connections}
						isLoading={isConnectionsLoading}
					/>
				</div>
			)}
		</div>
	);
}

/**
 * Sticky header + the shared tab bar (CONNECTOR_TABS) over a connections
 * rail + tab content. The connection-detail page renders the same bar in the
 * same order, so descending into a connection changes only the *contents* of
 * each tab, never which tabs exist or where they sit.
 *
 * Tabs are never hidden when a connector lacks a capability — a disappearing
 * tab is exactly the layout shift this bar exists to prevent. A connector with
 * no actions shows a disabled `Actions` tab instead, which also tells the user
 * the capability exists but is unavailable here.
 */
function ConnectorDetailShell({
	hero,
	connector,
	organizationId,
	ownerSlug,
	connectorKey,
	connections,
	isLoading,
	refetchConnections,
}: {
	hero: React.ReactNode;
	connector: ConnectorDefinitionItem;
	organizationId: string;
	ownerSlug: string;
	connectorKey: string;
	connections: ConnectionItem[];
	isLoading: boolean;
	refetchConnections: () => void;
}) {
	const navigate = useNavigate();
	const { tab } = Route.useSearch();
	const requestedTab = tab ?? "overview";
	const { isAdmin } = useMembers(organizationId);
	const hasActions = (connector.operations_summary?.total ?? 0) > 0;
	// Chat platforms (Slack/Discord): inbound chat + Behaviors, not the
	// operations.execute surface the Actions tab lists.
	const isChatConnector = Boolean(
		(connector.options_schema as { "x-lobu-chat-platform"?: string } | null)?.[
			"x-lobu-chat-platform"
		],
	);
	const activeTab = CONNECTOR_PAGE_TABS.some((t) => t.value === requestedTab)
		? requestedTab
		: "overview";

	return (
		<ConnectorPageShell
			header={hero}
			tabs={CONNECTOR_PAGE_TABS.map((t) => ({
				value: t.value,
				label: t.label,
			}))}
			value={activeTab}
			onValueChange={(next) =>
				void navigate({
					to: "/$owner/connectors/$connectorKey",
					params: { owner: ownerSlug, connectorKey },
					search: {
						tab: next === "overview" ? undefined : parseConnectorTab(next),
					},
					replace: true,
				})
			}
		>
			<TabsContent value="overview" className="mt-0 space-y-6">
				{!isLoading && connections.length > 0 ? (
					<ConnectorOverview
						connections={connections}
						connectorDef={connector}
						ownerSlug={ownerSlug}
						connectorKey={connectorKey}
					/>
				) : (
					<TabEmptyState
						icon={Plug}
						title="No activity yet"
						description="Add a connection to start using this connector. Manage them under Connections."
					/>
				)}
			</TabsContent>

			<TabsContent value="connections" className="mt-0 space-y-4">
				{/* Empty CTA (app install / create) + list of existing connections. */}
				<MainConnectorSurface
					connector={connector}
					organizationId={organizationId}
					ownerSlug={ownerSlug}
					connectorKey={connectorKey}
					connections={connections}
					isLoading={isLoading}
					refetchConnections={refetchConnections}
				/>
				{!isLoading && connections.length > 0 ? (
					<>
						<div className="flex items-center justify-between gap-2">
							<p className="text-sm text-muted-foreground">
								{connections.length} connection
								{connections.length === 1 ? "" : "s"}
							</p>
							<Button asChild size="sm" variant="outline">
								<Link
									to="/$owner/connectors/create/$connectorKey"
									params={{ owner: ownerSlug, connectorKey }}
								>
									<Plus className="h-3.5 w-3.5" />
									Add
								</Link>
							</Button>
						</div>
						<ConnectorConnectionsList
							connections={connections}
							connectorDef={connector}
							ownerSlug={ownerSlug}
							connectorKey={connectorKey}
							activeTab={activeTab}
						/>
					</>
				) : null}
			</TabsContent>

			<TabsContent value="actions" className="mt-0">
				{hasActions && isAdmin ? (
					<ConnectorActionsSection
						connector={connector}
						organizationId={organizationId}
					/>
				) : (
					<TabEmptyState
						icon={Plug}
						title="No actions available"
						description={
							hasActions && !isAdmin
								? "Only workspace admins can view and configure connector actions."
								: isChatConnector
									? "Chat connectors route messages through agents and Behaviors — they do not list callable operations here. Use Channels on a connection and agent chat to talk through this app."
									: "This connector does not expose agent operations yet."
						}
					/>
				)}
			</TabsContent>

			{/* Connector-level Settings: workspace auth, definition metadata, and
			    uninstall. Connection Settings is the same idea one level down. */}
			<TabsContent value="settings" className="mt-0">
				<ConnectorSetup
					connector={connector}
					organizationId={organizationId}
					ownerSlug={ownerSlug}
					connectionCount={connections.length}
				/>
			</TabsContent>
		</ConnectorPageShell>
	);
}

function ConnectorHero({
	connector,
	ownerSlug,
}: {
	connector: ConnectorDefinitionItem;
	ownerSlug: string;
}) {
	return (
		<DetailHeader
			breadcrumb={
				<DetailBreadcrumb
					crumbs={[
						<Link
							key="connectors"
							to="/$owner/connectors"
							params={{ owner: ownerSlug }}
							className={DETAIL_CRUMB_LINK_CLASS}

content.content:
140		ownerSlug: string;
141		isWorkspaceLoading: boolean;
142		connectorKey: string;
143		connectionId: number;
144		showAddFeed: boolean;
