160	
161		if (isWorkspaceLoading || isLoading || !organizationId) {
162			// Chrome-paint-first: render name + breadcrumb skeletons in the same
163			// position the loaded chrome will occupy, plus the two-column
164			// runs-left / form-right skeleton for the body, so nothing reflows
