184					>
185						Back to {connectorDef?.name ?? connectorKey}
186					</Link>
187				</div>
188			);
189		}
190	
191		const displayName = connectionLabel({
192			...connection,
193			connector_name: connection.connector_name ?? connectorDef?.name ?? null,
194		});
195	
196		// Chat connections have no sync runs on Overview — empty state, tab stays on.
197		const isChat = connection.facets?.chat ?? false;
198		const showActivity = !isChat;
199		const showActions = connection.has_operations === true;
200		const feedsTabLabel = isChat ? "Channels" : "Feeds";
201		const resolvedTab = resolveEnabledConnectorTab(
