210		);
211		// Main pane modes: feed detail > add feed form > the tabbed connection view.
212		const isDefaultMode = !feedId && !showAddFeed;
213		// Feed modes keep Feeds selected so the bar width/labels match the connection page.
214		const breadcrumbTab: ConnectorTabValue = isDefaultMode
215			? resolvedTab
216			: "feeds";
217	
218		const goToConnection = () =>
