228			});
229	
230		const connectionTabs = CONNECTION_PAGE_TABS.map((t) => ({
231			value: t.value,
232			label: t.value === "feeds" ? feedsTabLabel : t.label,
233		}));
234	
235		const navigateConnectionTab = (next: string) =>
