249		let mainPane: React.ReactNode;
250		// In the deeper modes the page is *about* the feed, so the heading names it
251		// and the connection moves into the trail. Previously the heading stayed on
252		// the connection and the mode leaked into the subtitle as " · Feed" /
253		// " · Add feed"; the breadcrumb carries that now.
254		let pageTitle = displayName;
255		// Feed detail replaces the connection's status/meta with the feed's own.
256		let headerStatus: React.ReactNode;
