258		// Deeper modes describe themselves rather than the connection.
259		let headerCaption: string | undefined;
260	
261		if (feedId) {
262			if (!feed) {
263				mainPane = (
264					<p className="text-sm text-muted-foreground">Feed not found.</p>
265				);
266				pageTitle = "Feed";
267			} else {
268				pageTitle = feedDisplayName(feed, connectorDef);
269				if (feed.kind === "streaming") {
270					// A chat channel is a streaming feed: its detail is the conversation
271					// (channel_messages lens), not a runs table. The page shell owns
272					// title + breadcrumb back, so the body omits its own chrome.
