300		}
301	
302		// The trail always names every ancestor, so the deeper modes (feed detail,
303		// add feed) show the connection they belong to as a real crumb instead of
304		// hiding it behind a linked title.
305		const crumbs = [
306			<Link
307				key="connectors"
308				to="/$owner/connectors"
309				params={{ owner: ownerSlug }}
310				className={DETAIL_CRUMB_LINK_CLASS}
311			>
312				Connectors
313			</Link>,
314			<Link
315				key="connector"
316				to="/$owner/connectors/$connectorKey"
