export interface ConnectionFacets {
	data: boolean;
	chat: boolean;
	actions: boolean;
	audience: boolean;
	inference: boolean;
	runtime: boolean;
}

export interface ConnectionItem {
	id: number;
	slug: string;
	organization_id: string;
	connector_key: string;
	display_name: string | null;
	/** Provider-side tenant this connection is scoped to (a Slack workspace, a
	 * Teams tenant, a GitHub org). Every connection is conceptually tenanted;
	 * the column is populated where routing needs it and NULL elsewhere. */
	external_tenant_id: string | null;
	status: string;
	config: Record<string, unknown> | null;
	error_message: string | null;
	created_by: string | null;
	created_by_username: string | null;
	created_at: string;
	updated_at: string;
	connector_name: string | null;
	auth_profile_slug: string | null;
	auth_profile_name: string | null;
	auth_profile_status: string | null;
	auth_profile_kind:
		| "env"
		| "oauth_app"
		| "oauth_account"
		| "browser_session"
		| "interactive"
		| null;
	app_auth_profile_slug: string | null;
	app_auth_profile_name: string | null;
	app_auth_profile_status: string | null;
	app_auth_profile_kind:
		| "env"
		| "oauth_app"
		| "oauth_account"
		| "browser_session"
		| "interactive"
		| null;
	/**
	 * Live event count. Present on the per-connection detail response
	 * (`handleGet`) but intentionally omitted from list responses
	 * (`handleList`) because the per-row supersedes anti-join was the
	 * dominant cost (1303ms → 2.3ms once dropped). For aggregate displays,
	 * use the events sparkline series instead of summing this field.
	 */
	event_count?: number;
	feed_count: number;
	connect_token: string | null;
	/** Entities this connection is directly tagged with (connections.entity_ids). */
	entity_ids: number[] | null;
	/**
	 * UNION of the connection's own entity_ids and any of its feeds' entity_ids,
	 * resolved to entity names (comma-separated). A connection counts under an
	 * entity if it is directly tagged OR one of its feeds is.
	 */
	entity_names: string | null;
	visibility: "org" | "private";
	/** If set, this connection runs on a specific device worker instead of the Lobu server (serverless). */
	device_worker_id: string | null;
	device_label: string | null;
	device_platform: string | null;
	device_worker_handle: string | null;
	device_online: boolean | null;
	device_last_seen_at: string | null;
	/** 'offline' when pinned to a device that hasn't checked in recently — runs wait for it. */
	device_status: "offline" | null;
	operations_summary?: OperationSummary;
	has_operations?: boolean;
	/** Derived capability facets — what this connection does (Stage 2b). */
	facets: ConnectionFacets;
	/**
	 * `managed` = Lobu-hosted OAuth install ("Add to Slack" / GitHub App);
	 * `byo` = you supplied the token/credentials; `null` = neither resolved.
	 */
	effective_credential_mode: "managed" | "byo" | null;
}

export interface OperationSummary {
	total: number;
	reads: number;
	writes: number;
=== FEED ===
export interface FeedItem {
	id: number;
	connection_id: number;
	display_name: string | null;
	feed_key: string;
	status: string;
	/** How the feed's rows arrive: collected (scheduled pull), virtual (live
	 * read at request time), or streaming (chat channel — pushed in real time,
	 * read from `channel_messages` as a conversation, never synced). */
	kind: "collected" | "virtual" | "streaming";
	config: Record<string, unknown> | null;
	entity_ids: number[] | null;
	entity_names?: string | null;
	connector_key: string;
	connector_name: string | null;
	connection_name: string | null;
	connection_status: string | null;
	/** Slack workspace/team id (`connections.external_tenant_id`) for managed
	 * installs; null for BYO / non-Slack. Needed to bind a streaming channel with
	 * the right team scope. */
	external_tenant_id: string | null;
	/** For a streaming (chat-channel) feed: the agent its channel is currently
	 * bound to, or null if unbound. Lets the Behaviors Listen picker avoid
	 * silently stealing a channel already owned by another agent. */
	target_agent_id?: string | null;
	auth_profile_kind:
		| "env"
		| "oauth_app"
		| "oauth_account"
		| "browser_session"
		| "interactive"
		| null;
	auth_profile_status: string | null;
	active_runs: number;
	event_count: number;
	last_sync_at: string | null;
	last_sync_status: string | null;
	next_run_at: string | null;
	created_at: string;
	updated_at: string;
	// Connector repair-agent fields (PR 2 — connector-repair-plumbing).
	// `repair_agent_id` is editable; the rest are observability fields.
	repair_agent_id: string | null;
	repair_thread_id: string | null;
	repair_attempt_count: number;
	last_repair_at: string | null;
	first_failure_at: string | null;
	// Device-worker binding of the parent connection (for "waiting on device" state).
	device_worker_id: string | null;
	device_label: string | null;
	device_platform: string | null;
	device_last_seen_at: string | null;
	device_online: boolean | null;
	device_status: "offline" | null;
}

export interface ConnectorRuntimeInfo {
	platforms: Array<"ios" | "android" | "macos" | "windows" | "linux">;
	scopes?: string[];
}

export interface ConnectorDefinitionItem {

