export interface ConnectionGroupSummary {
	id: number;
	display_name: string | null;
	feed_count: number;
}

export interface ConnectionConnectorGroup {
	connector_key: string;
	connector_name: string | null;
	favicon_domain: string | null;
	connection_count: number;
	connections: ConnectionGroupSummary[];
	/**
	 * Connector-level capability facets — the union across the group's members
	 * (chat = any member is a chat connection, data = any feeds or the connector
	 * declares feeds, actions = connector has operations, audience = connector in
	 * the ACL registry). Stage 2b.
	 */
	facets: ConnectionFacets;
}

export const useConnectionConnectorGroups = createQuery<
	[organizationId?: string | null, options?: { entityId?: number }],
	ConnectionConnectorGroup[]
>({
	queryKey: (organizationId, options) => [
		"connections",
		"groups",
		organizationId,
		options?.entityId,
	],
	tool: "manage_connections",
	body: (_orgId, options) => ({
		action: "list_connector_groups",
		entity_id: options?.entityId,
	}),
	transform: (r) => r.groups ?? [],
	enabled: (organizationId) => !!organizationId,
	staleTime: 60000,
});

export const useConnections = createQuery<
	[
		organizationId?: string | null,
		options?: {
			connectorKey?: string;
			status?: string;
			entityId?: number;
			createdBy?: string;
			connectionIds?: number[];
			limit?: number;
			enabled?: boolean;
		},
	],
	ConnectionItem[]
>({
	queryKey: (organizationId, options) => [
		"connections",
		organizationId,
		options?.connectorKey,
		options?.status,
		options?.entityId,
		options?.createdBy,
		options?.connectionIds,
		options?.limit,
	],
	tool: "manage_connections",
	body: (_orgId, options) => ({
		action: "list",
		connector_key: options?.connectorKey,
		status: options?.status,
		entity_id: options?.entityId,
		created_by: options?.createdBy,
		connection_ids: options?.connectionIds,
		limit: options?.limit,
	}),
	transform: (r) => r.connections ?? [],
	enabled: (organizationId, options) =>
		!!organizationId && (options?.enabled ?? true),
	// SSE pushes `{ keys: ['connections'] }` on changes (worker-api.ts:1316),
	// so we don't need to refetch on every mount.
	staleTime: 60000,
});

export const useConnectorDefinitions = createQuery<
	[organizationId?: string | null],
	ConnectorDefinitionItem[]
>({
	queryKey: (organizationId) => ["connector-definitions", organizationId],
	tool: "manage_catalog",
	body: () => ({
		action: "list_installed",
		kinds: ["connectors"],
		include_catalog: true,
	}),
	transform: (r) => {
		const items = r.installed?.connectors?.items as
			| InstalledItemWire[]
			| undefined;
		return (items ?? [])
			.filter((item) => item.detail?.installed !== false)
			.map(mapInstalledConnectorItem);
	},
	enabled: (organizationId) => !!organizationId,
	staleTime: 60000,
});

export async function fetchInstallableConnectorCatalog(
	orgContext?: string | ApiOrgContext,
): Promise<ConnectorDefinitionItem[]> {
	const result = await apiCall<{
		installed?: { connectors?: { items?: InstalledItemWire[] } };
	}>(
		"manage_catalog",
		{
			action: "list_installed",
			kinds: ["connectors"],
			include_catalog: true,
		},
		orgContext,
	);
	return (result.installed?.connectors?.items ?? []).map(
		mapInstalledConnectorItem,
	);
}

