const state = {
  page: 'overview',
  connectorFilter: 'all',
  connectorSearch: '',
  detailTab: 'overview'
};

const resources = [
  { id: 'overview', label: 'Overview' },
  { id: 'connectors', label: 'Connectors' },
  { id: 'devices', label: 'Devices' },
  { id: 'models', label: 'Models' },
  { id: 'runtimes', label: 'Runtimes' },
  { id: 'plan', label: 'UX plan' }
];

const connectors = [
  { id:'gmail', logo:'M', name:'Gmail', desc:'Email knowledge and actions', caps:['Data','Actions'], setup:'OAuth', state:'Connected', stateClass:'green', meta:'1 account · 2 data sources', group:'connected', detail:true },
  { id:'telegram', logo:'➤', name:'Telegram', desc:'Route bot conversations to an agent', caps:['Chat'], setup:'Bot token', state:'Connected', stateClass:'green', meta:'personal-agent', group:'connected', detail:true },
  { id:'chrome', logo:'◉', name:'Chrome', desc:'Browser context and typed browser actions', caps:['Data','Actions','On device'], setup:'Device pairing', state:'Online', stateClass:'green', meta:'2 profiles', group:'connected' },
  { id:'postgres', logo:'PG', name:'PostgreSQL', desc:'Collected memory or live read-only queries', caps:['Data'], setup:'Connection string', state:'Connected', stateClass:'green', meta:'1 query', group:'connected' },
  { id:'jira', logo:'J', name:'Jira', desc:'Live JQL reads and real-time issue events', caps:['Data','Live'], setup:'OAuth', state:'Connected', stateClass:'green', meta:'1 live scope', group:'connected' },
  { id:'linkedin', logo:'in', name:'LinkedIn', desc:'Browser-backed feeds plus human-handoff actions', caps:['Data','Actions','Browser'], setup:'Device session', state:'Needs attention', stateClass:'amber', meta:'11 data sources', group:'connected' },
  { id:'slack', logo:'#', name:'Slack', desc:'Mention, DM, or route channels to Lobu agents', caps:['Chat','Events'], setup:'App install', state:'Available', stateClass:'gray', meta:'Not connected', group:'available' },
  { id:'github', logo:'GH', name:'GitHub', desc:'Issues, PRs, commits, webhooks, and repo actions', caps:['Data','Actions','Events'], setup:'App install / OAuth', state:'Available', stateClass:'gray', meta:'Not connected', group:'available' },
  { id:'linear', logo:'L', name:'Linear', desc:'Live issue reads and webhook events', caps:['Data','Live','Events'], setup:'OAuth', state:'Available', stateClass:'gray', meta:'Not installed', group:'available' },
  { id:'website', logo:'W', name:'Website', desc:'Rendered web pages converted to structured memory', caps:['Data'], setup:'URL', state:'Available', stateClass:'gray', meta:'Not connected', group:'available' },
  { id:'webhook', logo:'↘', name:'Inbound webhook', desc:'Receive authenticated JSON as Lobu events', caps:['Events'], setup:'Bearer token', state:'Available', stateClass:'gray', meta:'Not installed', group:'available' }
];

const devices = [
  { id:'macbook-chrome', icon:'◉', name:'Burak’s MacBook Chrome', platform:'Chrome extension · v0.5.6', online:true, capabilities:7, connectors:4, errors:0, last:'Seen now', attached:['Chrome','Chrome history','Chrome bookmarks','Chrome downloads'] },
  { id:'mini-chrome', icon:'◉', name:'Burak Mac mini Chrome', platform:'Chrome extension · v0.5.6', online:true, capabilities:4, connectors:2, errors:0, last:'Seen now', attached:['Chrome','X (Twitter)'] },
  { id:'mac-mini', icon:'⌘', name:'Burak’s Mac mini', platform:'macOS · v14.2.0', online:false, capabilities:3, connectors:4, errors:0, last:'Seen 21 hours ago', attached:['Mac Computer Use','Reminders','WhatsApp (this Mac)','LinkedIn Takeout'] },
  { id:'macbook-pro', icon:'⌘', name:'Burak’s MacBook Pro', platform:'macOS · v0.1.0', online:false, capabilities:3, connectors:4, errors:0, last:'Seen 11 days ago', attached:['Apple Photos','Apple Screen Time','Local Folder','Calendar'] }
];

const models = [
  { id:'gemini', logo:'G', name:'Gemini', model:'gemini-2.5-pro', default:true, active:true, auth:'API key', modalities:['Text','Image'], agents:['personal-agent'] },
  { id:'openai', logo:'O', name:'OpenAI API', model:'gpt-4o-mini', default:false, active:true, auth:'API key', modalities:['Text','Image','TTS'], agents:['Builder','personal-agent'] },
  { id:'zai', logo:'Z', name:'z.ai', model:'glm-5.2', default:false, active:true, auth:'API key', modalities:['Text'], agents:['Builder','personal-agent'] }
];

function cap(text) { return `<span class="cap-badge">${text}</span>`; }
function status(text, cls='gray') { return `<span class="status ${cls}">${text}</span>`; }
function resourceIcon(text, cls='blue') { return `<div class="resource-icon ${cls}">${text}</div>`; }

function resourceTabs(active) {
  return `<div class="resource-tabs">${resources.map(r => `<button class="resource-tab ${active===r.id?'active':''}" onclick="navigate('${r.id}')">${r.label}</button>`).join('')}</div>`;
}

function banner() {
  return `<div class="prototype-banner"><span>◈</span><span><strong>Interactive UX prototype</strong> based on the live Lobu connector catalog, connection objects, device API, model-provider API, and sandbox API.</span><span class="banner-spacer"></span><button class="banner-link" onclick="openAuditModal()">Audit basis</button></div>`;
}

function pageHead(title, subtitle, actions='') {
  return `<div class="page-head"><div><h1 class="page-title">${title}</h1><p class="page-subtitle">${subtitle}</p></div>${actions?`<div class="page-actions">${actions}</div>`:''}</div>`;
}

function navigate(page) {
  state.page = page;
  state.detailTab = 'overview';
  document.getElementById('topCrumb').textContent = page === 'overview' ? 'Connect' : resources.find(r=>r.id===page)?.label || 'Connect';
  render();
  window.scrollTo({top:0, behavior:'smooth'});
}

function setDetailTab(tab) {
  state.detailTab = tab;
  render();
}

function detailTabs(tabs) {
  return `<div class="detail-tabs">${tabs.map(t => `<button class="detail-tab ${state.detailTab===t.id?'active':''}" onclick="setDetailTab('${t.id}')">${t.label}</button>`).join('')}</div>`;
}

function renderOverview() {
  return `${banner()}${pageHead('Connect', 'Give agents access to company data, conversations, devices, models, and secure execution—without forcing every resource into the same UI.', `<button class="btn" onclick="navigate('plan')">View UX plan</button><button class="btn primary" onclick="navigate('connectors')">Add connection</button>`)}
  ${resourceTabs('overview')}
  <div class="grid four">
    <div class="card summary-card clickable" onclick="navigate('connectors')">
      <div class="summary-top">${resourceIcon('⛓','blue')}<div><div class="summary-label">Connectors</div><div class="summary-meta">Data, chat, actions, events</div></div></div>
      <div class="summary-value">28 connections</div>
      <div class="summary-meta">Gmail, Jira, Telegram, Chrome, PostgreSQL…</div>
      <div class="summary-footer">Manage connectors →</div>
    </div>
    <div class="card summary-card clickable" onclick="navigate('devices')">
      <div class="summary-top">${resourceIcon('⌘','green')}<div><div class="summary-label">Devices</div><div class="summary-meta">Workers and local capabilities</div></div></div>
      <div class="summary-value">2 of 7 online</div>
      <div class="summary-meta">Chrome profiles and Lobu for Mac</div>
      <div class="summary-footer">View devices →</div>
    </div>
    <div class="card summary-card clickable" onclick="navigate('models')">
      <div class="summary-top">${resourceIcon('✦','purple')}<div><div class="summary-label">Models</div><div class="summary-meta">Inference providers</div></div></div>
      <div class="summary-value">3 active</div>
      <div class="summary-meta">Gemini is the workspace default</div>
      <div class="summary-footer">Manage models →</div>
    </div>
    <div class="card summary-card clickable" onclick="navigate('runtimes')">
      <div class="summary-top">${resourceIcon('□','amber')}<div><div class="summary-label">Runtimes</div><div class="summary-meta">Sandboxes for agent execution</div></div></div>
      <div class="summary-value">Built-in + Vercel</div>
      <div class="summary-meta">No external sandbox configured</div>
      <div class="summary-footer">Configure runtimes →</div>
    </div>
  </div>

  <div class="section grid two">
    <div>
      <div class="section-head"><h2 class="section-title">Needs attention</h2><span class="section-note">Human-readable issues across resource types</span></div>
      <div class="card attention-list">
        <div class="attention-row"><div class="mini-icon">⌘</div><div><div class="row-title">Burak’s Mac mini is offline</div><div class="row-sub">Computer Use, Reminders, and local WhatsApp depend on this device.</div></div><button class="btn small" onclick="navigate('devices')">Open</button></div>
        <div class="attention-row"><div class="mini-icon">C</div><div><div class="row-title">Google Calendar needs repair</div><div class="row-sub">The connection is active, but its recent sync health needs attention.</div></div><button class="btn small" onclick="showToast('Repair flow would open here')">Repair</button></div>
        <div class="attention-row"><div class="mini-icon">in</div><div><div class="row-title">LinkedIn browser session is unavailable</div><div class="row-sub">Browser-backed collection cannot run until an Owletto profile is online.</div></div><button class="btn small" onclick="navigate('devices')">Find device</button></div>
      </div>
    </div>
    <div>
      <div class="section-head"><h2 class="section-title">What changed in this proposal</h2><span class="section-note">The key product decision</span></div>
      <div class="card principle-card">
        <div class="principle-kicker">Resource-first architecture</div>
        <div class="principle-title">Stop treating everything as a connector.</div>
        <div class="principle-copy">The current page merges four different backend systems. The new hub keeps one visual language, but gives each resource the detail screen it actually needs.</div>
        <div class="principle-flow"><span class="flow-pill">Connectors</span><span class="flow-arrow">→</span><span class="flow-pill">Devices</span><span class="flow-arrow">→</span><span class="flow-pill">Models</span><span class="flow-arrow">→</span><span class="flow-pill">Runtimes</span></div>
      </div>
    </div>
  </div>

  <div class="section">
    <div class="section-head"><h2 class="section-title">Recently used connections</h2><span class="section-note">Users see outcomes and health, not raw run logs</span></div>
    <div class="card connector-list">
      ${connectorRow(connectors[0])}${connectorRow(connectors[1])}${connectorRow(connectors[2])}${connectorRow(connectors[3])}

