export interface DeviceWorkerItem {
	/** Surrogate id; pass this as a connection's device_worker_id to pin it here. */
	id: string;
	worker_id: string;
	platform: string | null;
	app_version: string | null;
	capabilities: string[];
	label: string | null;
	last_seen_at: string;
	online: boolean;
	/** Workspace this device is attached to (its connectors live there). */
	organization_id: string | null;
	organization_name: string | null;
	organization_slug: string | null;
	/** How many connections are currently pinned to this device. */
	connector_count: number;
	/** Of those, how many are in an error state. */
	connector_error_count: number;
	/** Most recent successful/attempted feed sync across this device's connections. */
	last_sync_at: string | null;
	/** Connections pinned to this device — for cross-linking back into the connection. */
	connectors: Array<{
		connection_id: number;
		connector_key: string;
		display_name: string;
		status: string;
		organization_slug: string | null;
	}>;
}

