function feedExpanded(connId, f){
  var runs = [["Today 14:02","took 3s","+12 items","ok"],["Today 13:47","took 2s","+3 items","ok"],
              ["Today 13:32","took 2s","no change","ok"]];
  var stalled = f.tone === "id" && f.stat === "Stalled";
  var waiting = f.tone === "wn";
  var virtual = f.kind === "virtual";

  var head = virtual
    ? '<div class="ban info" style="margin-top:0"><span class="gl">◇</span><span class="grow">'
      + '<b>Nothing is stored for this source</b>It is read live from the provider each time an agent asks, '
      + 'so there is no sync history and no item count.</span></div>'
    : '<dl class="strip" style="margin-top:0;background:var(--surface)">'
      + '<div><dt>In memory</dt><dd>'+esc(f.count)+'</dd></div>'
      + '<div><dt>Last run</dt><dd>'+(stalled?"failed":waiting?"waiting":"+12 items")+'</dd></div>'
      + '<div><dt>Next run</dt><dd>'+(stalled?"held":waiting?"when device wakes":"in 13 min")+'</dd></div>'
      + '<div><dt>Active runs</dt><dd>0</dd></div></dl>';

  var history = virtual ? "" :
    '<div style="display:flex;align-items:center;justify-content:space-between;margin:18px 0 6px">'
    + '<span style="font-size:12px;font-weight:600">Recent syncs</span>'
    + '<button class="b sm gh" data-toast="Would open Activity filtered to this source">View in Activity ›</button></div>'
    + '<div class="rows">'
    + (stalled
        ? '<div class="row" style="padding:7px 0"><span class="grow"><span class="mt" style="margin:0">'
          + '26 July 09:14</span></span><span class="rt">401 from GitHub</span>'+st("Failed","bd")+'</div>'
        : waiting
          ? '<div class="row" style="padding:7px 0"><span class="grow"><span class="mt" style="margin:0">'
            + 'Today 09:07 <span style="color:var(--faint)">·</span> took 1s</span></span>'
            + '<span class="rt">+4 items</span>'+st("OK","ok")+'</div>'
          : runs.map(function(r){
              return '<div class="row" style="padding:7px 0"><span class="grow"><span class="mt" style="margin:0">'
                + esc(r[0])+' <span style="color:var(--faint)">·</span> '+esc(r[1])+'</span></span>'
                + '<span class="rt">'+esc(r[2])+'</span>'+st("OK","ok")+'</div>';
            }).join(''))
    + '</div>';

  var actions = '<div style="display:flex;gap:8px;margin-top:18px;flex-wrap:wrap">'
    + (virtual ? '' : '<button class="b sm" data-toast="manage_feeds.trigger_feed">Sync now</button>')
    + '<button class="b sm gh" data-toast="manage_feeds.delete_feed — would confirm first">Remove this source</button></div>';

  return '<div class="exp">' + head + feedConfigRows(connId, f) + history + actions + '</div>';
}

/* Settings for the three non-connection resources. */
function settingsRows(kind, obj){
  var fields;
  if(kind==="device"){
    fields=[["Name",obj.name,"Rename","devices.label"],
            ["Worker version",obj.platform,"—","app_version"],
            ["Pairing","Paired to Acme","Unpair","organization_id"]];
  } else if(kind==="model"){
    fields=[["Name",obj.name,"Rename","displayName"],
            ["API key","••••••••••••","Replace","credential · secret"],
            ["Endpoint",obj.custom?"Custom base URL set":"Provider default","Change","hasCustomUpstream"],
            ["Workspace default",obj.def?"Yes":"No","Change","isDefault"]];
  } else {
    fields=[["Name",obj.name,"Rename","name"],
            ["Provider",obj.details[0][1],"—","providerKind"],
            ["Credentials",obj.connected?"Stored in the vault":"Not set","Replace","connected"]];
  }
  if(!state.settings){
    return '<button class="disc" data-settings="1"><span class="car">▸</span> Settings '
      + '<span style="color:var(--faint)">— '+esc(fields.map(function(f){return f[0].toLowerCase();}).join(", "))+', remove</span></button>';
  }
  return '<button class="disc" data-settings="1"><span class="car">▾</span> Settings</button>'
    + '<div class="rows" style="margin-top:6px">'
    + fields.map(function(f){
        return '<div class="row"><span class="grow"><span class="nm">'+esc(f[0])+'</span>'
          + '<span class="mt" style="display:block">'+esc(f[1])+'</span></span>'
          + '<span class="op" title="'+esc(f[3])+'">'+esc(f[3].split(" · ")[0])+'</span>'
          + (f[2]==="—" ? '<span class="rt">read only</span>'
              : '<button class="b sm gh" data-toast="Writes '+esc(f[3])+'">'+esc(f[2])+'</button>')+'</div>';
      }).join('') + '</div>'
    + '<div class="ban bad" style="margin-top:14px"><span class="gl">⌫</span>'
    + '<span class="grow"><b>Remove '+esc(obj.name)+'</b>'
    + (kind==="device" ? 'Unpairs the machine. Connectors pinned to it stop until you pin them elsewhere.'
      : kind==="model" ? 'Agents routing to this provider fall back to the workspace default.'
      : 'Agents fall back to the built-in runtime.')+'</span>'
    + '<button class="b sm fix" data-toast="Would ask for confirmation">Remove</button></div>';
}

