      }).join('') + '</div>';
}

function feedList(c, fl){
  // Sources are usually 2-5. When a connection has many (a Slack with 24 bound
  // channels, a Gmail with 14 labels) the list caps and the unbound/failing ones
  // sort up, so the rows that need a person are never below the fold.
  var sorted = fl.slice().sort(function(a,b){
    var aw = (a.kind==="streaming" && !a.agent) || a.tone==="bd" || a.tone==="wn" ? 0 : 1;
    var bw = (b.kind==="streaming" && !b.agent) || b.tone==="bd" || b.tone==="wn" ? 0 : 1;
    return aw-bw;
  });
  var showAll = !!state.showAllFeeds[c.id];
  var capped = !showAll && sorted.length > FEED_CAP;
  var shown = capped ? sorted.slice(0, FEED_CAP) : sorted;
  var html = '';
  if(sorted.length > 12){
    html += '<div style="margin-bottom:8px"><span class="inp" style="padding:6px 11px">Search '
      + sorted.length + (c.kind==="chat"?' channels':' sources') + '…</span></div>';
  }
  html += '<div class="rows">'+shown.map(function(f){ return feedRow(c,f); }).join('')+'</div>';
  if(capped){
    html += '<button class="b sm gh" style="margin-top:10px" data-showall="feeds:'+c.id+'">Show all '
      + sorted.length + ' &nbsp;›</button>';
  }
  return html;
}

