# 1) centre the column, matching the agents pages (mx-auto w-full max-w-3xl)
rep(".col{width:100%;max-width:760px;}",
    ".col{width:100%;max-width:760px;margin:0 auto;}")

# 2) channels are Behaviour projections, not agent bindings
rep('''    { id:"support", name:"#support", kind:"streaming", count:"2,140", agent:"Support bot", tone:"ok" },
    { id:"eng", name:"#eng", kind:"streaming", count:"870", agent:"Builder", tone:"ok" },
    { id:"general", name:"#general", kind:"streaming", count:"0", agent:null, tone:"id" }''',
'''    // A channel is not bound to an agent. One or more Behaviors carry an event
    // trigger matching this channel_id, and `behavior_message_subscriptions` is
    // a VIEW over watchers.triggers with NO uniqueness — several agents can
    // listen to one channel. `link:true` marks the system:chat-link Behavior,
    // the one that replies; the rest read the channel silently.
    { id:"support", name:"#support", kind:"streaming", count:"2,140", tone:"ok",
      bhv:[{n:"Replies in #support", a:"Support bot", link:true}] },
    { id:"eng", name:"#eng", kind:"streaming", count:"870", tone:"ok",
      bhv:[{n:"Replies in #eng", a:"Builder", link:true},
