    if(i<3) b.push({n:"Replies in "+c, a:"Builder", link:true});
    else if(i===4) b.push({n:"Replies in "+c, a:"Support bot", link:true});
    if(i%5===2) b.push({n:"Incident digest", a:"Analyst", link:false});
    if(i>=5 && i%3===1) b.push({n:"Release notes watch", a:"Analyst", link:false});
    return { id:"ch"+i, name:c, kind:"streaming", count:String(((i*137)%900)+40),
             bhv:b, tone: b.length?"ok":"id" };''')

# 3) row rendering derived from the subscription list
rep('''function feedRow(c, f){
  if(f.kind==="streaming"){
    return '<button class="row act" '+go("channel/"+f.id)+'>'
      + '<span class="grow"><span class="nm">'+esc(f.name)+'</span><span class="mt" style="display:block">'
      + (f.agent ? 'Answered by <span style="color:var(--ink)">'+esc(f.agent)+'</span>' : 'No agent assigned, so nothing is answered here')
      + '</span></span>'
