      + '</button>';
  }''',
'''/* Who listens to a channel. This is a LIST, never one agent: the streaming feed
   row exists only because some Behavior has a message.created trigger matching
   its channel_id, and nothing stops a second Behavior matching the same one.
   The list payload carries only `target_agent_id`, which is a LIMIT 1 subquery
   over that view with no ORDER BY — it names an ARBITRARY listener. So the row
   states what one id can honestly support (someone replies, or only readers)
   and the channel page reads the full set. */
function bhvOf(f){ return f.bhv || []; }
function replier(f){
  var b = bhvOf(f);
  for(var i=0;i<b.length;i++){ if(b[i].link) return b[i]; }
  return null;
}
function channelLine(f){
  var b = bhvOf(f), r = replier(f);
  if(!b.length) return 'Nothing listens here';
  var rest = b.length - (r ? 1 : 0);
  var tail = rest ? ' <span style="color:var(--faint)">·</span> '+rest+' also reading' : '';
  if(r) return '<span style="color:var(--ink)">'+esc(r.a)+'</span> replies'+tail;
  return esc(b[0].a)+' reads this, nothing replies'+(b.length>1?' <span style="color:var(--faint)">·</span> '+(b.length-1)+' more':'');
}

function feedRow(c, f){
  if(f.kind==="streaming"){
    var r = replier(f);
    return '<button class="row act" '+go("channel/"+f.id)+'>'
      + '<span class="grow"><span class="nm">'+esc(f.name)+'</span><span class="mt" style="display:block">'
      + channelLine(f) + '</span></span>'
      + '<span class="rt">'+esc(f.count)+(f.count!=="0"?" in memory":"")+'</span>'
