function feedExpanded(connId, f){
  var runs = [["Today 14:02","took 3s","+12 items","ok"],["Today 13:47","took 2s","+3 items","ok"],
              ["Today 13:32","took 2s","no change","ok"]];
  var stalled = f.tone === "id" && f.stat === "Stalled";
  var waiting = f.tone === "wn";
  var virtual = f.kind === "virtual";

  var head = virtual
    ? '<div class="ban info" style="margin-top:0"><span class="gl">◇</span><span class="grow">'
      + '<b>Nothing is stored for this source</b>It is read live from the provider each time an agent asks, '
      + 'so there is no sync history and no item count.</span></div>'
    : '<dl class="strip" style="margin-top:0;background:var(--surface)">'
      + '<div><dt>In memory</dt><dd>'+esc(f.count)+'</dd></div>'
      + '<div><dt>Last run</dt><dd>'+(stalled?"failed":waiting?"waiting":"+12 items")+'</dd></div>'
      + '<div><dt>Next run</dt><dd>'+(stalled?"held":waiting?"when device wakes":"in 13 min")+'</dd></div>'
      + '<div><dt>Active runs</dt><dd>0</dd></div></dl>';

  var history = virtual ? "" :
    '<div style="display:flex;align-items:center;justify-content:space-between;margin:18px 0 6px">'
    + '<span style="font-size:12px;font-weight:600">Recent syncs</span>'
    + '<button class="b sm gh" data-toast="Would open Activity filtered to this source">View in Activity ›</button></div>'
    + '<div class="rows">'
    + (stalled
