document.addEventListener("click", function(e){
  var t = e.target;
  var el = t.closest ? t.closest("[data-go],[data-toast],[data-feed],[data-settings],[data-group],[data-showall]") : null;
  if(!el) return;
  if(el.hasAttribute("data-go")){ e.preventDefault(); navigate(el.getAttribute("data-go")); return; }
  if(el.hasAttribute("data-group")){
    var g = el.getAttribute("data-group");
    state.openGroup[g] = !state.openGroup[g];
    renderView(); return;
  }
  if(el.hasAttribute("data-showall")){
    var v = el.getAttribute("data-showall");
    if(v === "conns") state.showAllConns = true;
    else state.showAllFeeds[v.split(":")[1]] = true;
    renderView(); return;
  }
  if(el.hasAttribute("data-feed")){
    var f = el.getAttribute("data-feed");
    state.openFeed = (state.openFeed === f) ? null : f;
    renderView(); return;
  }
  if(el.hasAttribute("data-settings")){ state.settings = !state.settings; renderView(); return; }
  if(el.hasAttribute("data-toast")){ toast(el.getAttribute("data-toast")); return; }
});

document.getElementById("scaleBtn").addEventListener("click", function(){
  state.busy = !state.busy;
  state.showAllConns = false; state.showAllFeeds = {}; state.openGroup = {}; state.openFeed = null;
  this.classList.toggle("on", state.busy);
  this.textContent = state.busy ? "Busy workspace · on" : "Busy workspace";
  toast(state.busy ? "34 connections, one with 24 channels" : "Back to 8 connections");
  if(currentRoute().indexOf("c/")===0) navigate("connectors"); else render();
});
document.getElementById("notesBtn").addEventListener("click", toggleNotes);
window.addEventListener("hashchange", function(){
  state.openFeed = null; state.settings = false;
  render();
  window.scrollTo({ top:0 });
});

if(!location.hash) location.hash = "#/connectors";
render();
})();
</script>
