58	export const Route = createFileRoute(
59		"/$owner/connectors/$connectorKey/$connectionId",
60	)({
61		validateSearch: (search: Record<string, unknown>) =>
62			pruneSearch({
63				tab: search.tab === undefined ? undefined : parseConnectorTab(search.tab),
64				addFeed:
65					search.addFeed === true || search.addFeed === "true" ? true : undefined,
66				feedId:
67					typeof search.feedId === "number"
68						? search.feedId
69						: typeof search.feedId === "string" && /^\d+$/.test(search.feedId)
70							? Number(search.feedId)
71							: undefined,
72			}),
73		loaderDeps: ({ search: { feedId } }) => ({ feedId }),
74		loader: ({ context: { queryClient }, params, deps }) => {
75			// Fire-and-forget — workspace + connection prefetches warm the cache
76			// but never block paint. ConnectionDetailView renders its skeleton
77			// via isWorkspaceLoading until everything resolves. `useFeeds` is
78			// only consumed on feedId deep-links so we chain its prefetch behind
79			// workspace too.
80			void queryClient
81				.fetchQuery(
82					useWorkspaceRoot.queryOptions(params.owner, { slug: params.owner }),
83				)
84				.then((ws) => {
85					const orgId = ws?.workspace?.id;
86					if (!orgId) return;
87					void queryClient.prefetchQuery(
88						useConnections.queryOptions(orgId, {
89							connectorKey: params.connectorKey,
90						}),
91					);
92					void queryClient.prefetchQuery(
93						useConnectorDefinitions.queryOptions(orgId),
94					);
95					if (deps.feedId !== undefined) {
96						void queryClient.prefetchQuery(
97							useFeeds.queryOptions(Number(params.connectionId)),
98						);
99					}
100				})
101				.catch(() => {
102					// Page handles missing-workspace; swallow loader errors here.
103				});
104		},
105		component: ConnectionDetailRoute,
106	});
107	
108	function ConnectionDetailRoute() {
