import { createFileRoute, Link, useNavigate } from "@tanstack/react-router";
import { MessageSquare, Zap } from "lucide-react";
import {
	ConnectorMark,
	extractOAuthDomain,
} from "@/components/connectors/connector-display";
import { ConnectorPageShell } from "@/components/connectors/connector-page-shell";
import {
	ConnectionFeedsList,
	connectionTabSearch,
} from "@/components/connectors/connector-scope-lists";
import {
	CONNECTION_PAGE_TABS,
	type ConnectorTabValue,
	parseConnectorTab,
	resolveEnabledConnectorTab,
} from "@/components/connectors/connector-tabs";
import {
	DETAIL_CRUMB_LINK_CLASS,
	DetailBreadcrumb,
	DetailHeader,
} from "@/components/connectors/detail-header";
import { ActionRunner } from "@/components/entity-tabs/connections-tab/action-runner";
import {
	ADD_FEED_DESCRIPTION,
	AddFeedForm,
} from "@/components/entity-tabs/connections-tab/add-feed-form";
import { ConnectionChannelFeed } from "@/components/entity-tabs/connections-tab/connection-channel-feed";
import {
	ConnectionFeedDetail,
	FeedHeaderMeta,
	FeedStatusBadges,
	feedDisplayName,
} from "@/components/entity-tabs/connections-tab/connection-feed-detail";
import {
	ConnectionActionsSection,
	ConnectionSettingsTab,
} from "@/components/entity-tabs/connections-tab/connection-settings-tab";
import { DeviceFoldersPanel } from "@/components/entity-tabs/connections-tab/device-folders-panel";
import { TabEmptyState } from "@/components/entity-tabs/tab-states";
import { OwnerWorkspaceGate } from "@/components/owner-workspace-gate";
import { RunsLayoutSkeleton } from "@/components/runs/runs-layout-skeleton";
import { RunsPanel } from "@/components/runs/runs-panel";
import { Skeleton } from "@/components/ui/skeleton";
import { StatusBadge } from "@/components/ui/status-badge";
import { TabsContent } from "@/components/ui/tabs";
import {
	useConnections,
	useConnectorDefinitions,
	useFeeds,
} from "@/lib/api/connections";
import { useWorkspaceRoot } from "@/lib/api/entities";
import { connectionLabel } from "@/lib/connection-label";
import { connectionDisplayError } from "@/lib/device-pin-tombstone";
import { pruneSearch } from "@/lib/router-search";
import { getStatusVariant } from "@/lib/status-variants";

export const Route = createFileRoute(
	"/$owner/connectors/$connectorKey/$connectionId",
)({
	validateSearch: (search: Record<string, unknown>) =>
		pruneSearch({
			tab: search.tab === undefined ? undefined : parseConnectorTab(search.tab),
			addFeed:
				search.addFeed === true || search.addFeed === "true" ? true : undefined,
			feedId:
				typeof search.feedId === "number"
					? search.feedId
					: typeof search.feedId === "string" && /^\d+$/.test(search.feedId)
						? Number(search.feedId)
						: undefined,
		}),
	loaderDeps: ({ search: { feedId } }) => ({ feedId }),
	loader: ({ context: { queryClient }, params, deps }) => {
		// Fire-and-forget — workspace + connection prefetches warm the cache
		// but never block paint. ConnectionDetailView renders its skeleton
		// via isWorkspaceLoading until everything resolves. `useFeeds` is
		// only consumed on feedId deep-links so we chain its prefetch behind
		// workspace too.
		void queryClient
			.fetchQuery(
				useWorkspaceRoot.queryOptions(params.owner, { slug: params.owner }),
			)
			.then((ws) => {
				const orgId = ws?.workspace?.id;
				if (!orgId) return;
				void queryClient.prefetchQuery(
					useConnections.queryOptions(orgId, {
						connectorKey: params.connectorKey,
					}),
				);
				void queryClient.prefetchQuery(
					useConnectorDefinitions.queryOptions(orgId),
				);
				if (deps.feedId !== undefined) {
					void queryClient.prefetchQuery(
						useFeeds.queryOptions(Number(params.connectionId)),
					);
				}
			})
			.catch(() => {
				// Page handles missing-workspace; swallow loader errors here.
			});
	},
	component: ConnectionDetailRoute,
});

function ConnectionDetailRoute() {
	const { owner, connectorKey, connectionId } = Route.useParams();
	const { addFeed, feedId, tab } = Route.useSearch();
	return (
		<OwnerWorkspaceGate owner={owner}>
			{(props) => (
				<ConnectionDetailView
					organizationId={props.organizationId}
					ownerSlug={props.ownerSlug}
					isWorkspaceLoading={props.isWorkspaceLoading}
					connectorKey={connectorKey}
					connectionId={Number(connectionId)}
					showAddFeed={addFeed === true}
					feedId={feedId}
					activeTab={tab ?? "overview"}
				/>
			)}
		</OwnerWorkspaceGate>
	);
}

function ConnectionDetailView({
	organizationId,
	ownerSlug,
	isWorkspaceLoading,
	connectorKey,
	connectionId,
	showAddFeed,
	feedId,
	activeTab,
}: {
	organizationId: string | null;
	ownerSlug: string;
	isWorkspaceLoading: boolean;
	connectorKey: string;
	connectionId: number;
	showAddFeed: boolean;
	feedId: number | undefined;
	activeTab: ConnectorTabValue;
}) {
	const navigate = useNavigate();
	const { data: connections = [], isLoading } = useConnections(
		organizationId ?? "",
		{ connectorKey },
	);
	const { data: connectorDefs = [] } = useConnectorDefinitions(
		organizationId ?? "",
	);
	const { data: feeds = [] } = useFeeds(feedId ? connectionId : null);
	const connection = connections.find((c) => c.id === connectionId);
	const connectorDef = connectorDefs.find((d) => d.key === connectorKey);
	const feed = feedId ? feeds.find((f) => f.id === feedId) : null;

	if (isWorkspaceLoading || isLoading || !organizationId) {
		// Chrome-paint-first: render name + breadcrumb skeletons in the same
		// position the loaded chrome will occupy, plus the two-column
		// runs-left / form-right skeleton for the body, so nothing reflows
		// when data lands.
		return (
			<div className="flex flex-1 flex-col gap-4">
				<div className="flex flex-wrap items-baseline gap-x-3 gap-y-1">
					<Skeleton className="h-7 w-56" />
					<Skeleton className="h-4 w-24" />
				</div>
				<RunsLayoutSkeleton />
			</div>
		);
	}
	if (!connection) {
		return (
			<div>
				<p className="text-sm text-muted-foreground">Connection not found.</p>
				<Link
					to="/$owner/connectors/$connectorKey"
					params={{ owner: ownerSlug, connectorKey }}
					className="mt-2 inline-block text-sm text-primary hover:underline"
				>
					Back to {connectorDef?.name ?? connectorKey}
				</Link>
			</div>
		);
	}

	const displayName = connectionLabel({
		...connection,
		connector_name: connection.connector_name ?? connectorDef?.name ?? null,
	});

	// Chat connections have no sync runs on Overview — empty state, tab stays on.
	const isChat = connection.facets?.chat ?? false;
	const showActivity = !isChat;
	const showActions = connection.has_operations === true;
	const feedsTabLabel = isChat ? "Channels" : "Feeds";
	const resolvedTab = resolveEnabledConnectorTab(
		activeTab,
		{
			overview: true,
			feeds: true,
			actions: true,
			settings: true,
		},
		CONNECTION_PAGE_TABS,
	);
	// Main pane modes: feed detail > add feed form > the tabbed connection view.
	const isDefaultMode = !feedId && !showAddFeed;
	// Feed modes keep Feeds selected so the bar width/labels match the connection page.
	const breadcrumbTab: ConnectorTabValue = isDefaultMode
		? resolvedTab
		: "feeds";

	const goToConnection = () =>
		void navigate({
			to: "/$owner/connectors/$connectorKey/$connectionId",
			params: {
				owner: ownerSlug,
				connectorKey,
				connectionId: String(connectionId),
			},
			search: { tab: "feeds" },
			replace: true,
		});

	const connectionTabs = CONNECTION_PAGE_TABS.map((t) => ({
		value: t.value,
		label: t.value === "feeds" ? feedsTabLabel : t.label,
	}));

	const navigateConnectionTab = (next: string) =>
		void navigate({
			to: "/$owner/connectors/$connectorKey/$connectionId",
			params: {
				owner: ownerSlug,
				connectorKey,
				connectionId: String(connectionId),
			},
			// Clear feedId / addFeed when switching tabs.
			search: {
				tab: next === "overview" ? undefined : parseConnectorTab(next),
			},
			replace: true,
		});
	let mainPane: React.ReactNode;
	// In the deeper modes the page is *about* the feed, so the heading names it
	// and the connection moves into the trail. Previously the heading stayed on
	// the connection and the mode leaked into the subtitle as " · Feed" /
	// " · Add feed"; the breadcrumb carries that now.
	let pageTitle = displayName;
	// Feed detail replaces the connection's status/meta with the feed's own.
	let headerStatus: React.ReactNode;
	let headerMeta: React.ReactNode;
	// Deeper modes describe themselves rather than the connection.
	let headerCaption: string | undefined;

	if (feedId) {
		if (!feed) {
			mainPane = (
				<p className="text-sm text-muted-foreground">Feed not found.</p>
			);
			pageTitle = "Feed";
		} else {
			pageTitle = feedDisplayName(feed, connectorDef);
			if (feed.kind === "streaming") {
				// A chat channel is a streaming feed: its detail is the conversation
				// (channel_messages lens), not a runs table. The page shell owns
				// title + breadcrumb back, so the body omits its own chrome.
				mainPane = <ConnectionChannelFeed feed={feed} hideHeader />;
				headerCaption = "chat channel";
			} else {
				// The feed's status/meta ride in the page header rather than a second
				// header inside the pane, so the feed level looks like every other.
				headerStatus = <FeedStatusBadges feed={feed} ownerSlug={ownerSlug} />;
				headerMeta = <FeedHeaderMeta feed={feed} />;
				mainPane = (
					<ConnectionFeedDetail
						feed={feed}
						connectorDef={connectorDef}
						ownerSlug={ownerSlug}
					/>
				);
			}
		}
	} else if (showAddFeed) {
		mainPane = (
			<AddFeedForm
				onClose={goToConnection}
				organizationId={organizationId}
				connections={[connection]}
				connectorDefinitions={connectorDefs}
			/>
		);
		pageTitle = "Add feed";
		headerCaption = ADD_FEED_DESCRIPTION;
	}

	// The trail always names every ancestor, so the deeper modes (feed detail,
	// add feed) show the connection they belong to as a real crumb instead of
	// hiding it behind a linked title.
	const crumbs = [
		<Link
			key="connectors"
			to="/$owner/connectors"
			params={{ owner: ownerSlug }}
			className={DETAIL_CRUMB_LINK_CLASS}
		>
			Connectors
		</Link>,
		<Link
			key="connector"
			to="/$owner/connectors/$connectorKey"
			params={{ owner: ownerSlug, connectorKey }}
			search={connectionTabSearch(breadcrumbTab)}
			className={DETAIL_CRUMB_LINK_CLASS}
		>
			{connectorDef?.name ?? connectorKey}
		</Link>,
	];
	if (!isDefaultMode) {
		crumbs.push(
			<Link
				key="connection"
				to="/$owner/connectors/$connectorKey/$connectionId"
				params={{
					owner: ownerSlug,
					connectorKey,
					connectionId: String(connectionId),
				}}
				search={connectionTabSearch(breadcrumbTab)}
				className={DETAIL_CRUMB_LINK_CLASS}
			>
				{displayName}
			</Link>,
		);
	}

	// Caption: errors always; feed modes may set a short kind line. Never
	// "Discord · BYO" — breadcrumb + title already name the connection.
	const errorText = isDefaultMode ? connectionDisplayError(connection) : null;
	const caption = headerCaption ?? errorText ?? undefined;

	const header = (
		<DetailHeader
			breadcrumb={<DetailBreadcrumb crumbs={crumbs} />}
			icon={
				connectorDef ? (
					<ConnectorMark
						icon={connectorDef.icon}
						name={connectorDef.name}
						faviconDomain={
							connectorDef.favicon_domain ??
							extractOAuthDomain(connectorDef.auth_schema)
						}
					/>
				) : null
			}
			title={pageTitle}
			status={
				headerStatus ?? (
					<StatusBadge status={getStatusVariant(connection.status)} showDot>
						{connection.status}
					</StatusBadge>
				)
			}
			meta={headerMeta}
			caption={caption}
			captionTone={errorText ? "error" : "muted"}
		/>
	);

	// Feed detail / add-feed: Feeds tab selected; body is the feed pane.
	// Switching tabs clears feedId via navigateConnectionTab.
	if (!isDefaultMode) {
		return (
			<ConnectorPageShell
				header={header}
				tabs={connectionTabs}
				value="feeds"
				onValueChange={navigateConnectionTab}
			>
				<div className="mt-0">{mainPane}</div>
			</ConnectorPageShell>
		);
	}

	return (
		<ConnectorPageShell
			header={header}
			tabs={connectionTabs}
			value={resolvedTab}
			onValueChange={navigateConnectionTab}
		>
			{connectorKey === "local.directory" && (
				<DeviceFoldersPanel connectionId={connectionId} />
			)}
			<TabsContent value="overview" className="mt-0">
				{showActivity ? (
					<RunsPanel scope={{ connectionId }} ownerSlug={ownerSlug} />
				) : (
					<TabEmptyState
						icon={MessageSquare}
						title="No sync activity"
						description="This is a live chat connection — its channels stream in real time rather than syncing on a schedule. Open Channels to bind them."
					/>
				)}
			</TabsContent>

			<TabsContent value="feeds" className="mt-0">
				<ConnectionFeedsList
					connection={connection}
					ownerSlug={ownerSlug}
					connectorKey={connectorKey}
					connectorDef={connectorDef}
				/>
			</TabsContent>

			<TabsContent value="actions" className="mt-0 space-y-6">
				{showActions ? (
					<>
						<ConnectionActionsSection connection={connection} />
						<ActionRunner connectionId={connectionId} />
					</>
				) : (
					<TabEmptyState
						icon={Zap}
						title="No actions available"
						description={
							isChat
								? "Chat connections talk through agents and Behaviors, not the operations runner. Bind channels under Channels and message the bot in Slack/Discord."
								: "This connection has no callable operations configured."
						}
					/>
				)}
			</TabsContent>

			<TabsContent value="settings" className="mt-0">
				<div className="max-w-3xl">
					<ConnectionSettingsTab
						connection={connection}
						connectorDef={connectorDef}
						ownerSlug={ownerSlug}
					/>
				</div>
			</TabsContent>
		</ConnectorPageShell>
	);
}

