import type { ReactNode } from "react";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";

/**
 * Connector / connection page chrome — single column, same width at every depth:
 *
 *   header (max-w-3xl)
 *   tabs   (same width — Connections vs Feeds is only a label swap)
 *   body
 *
 * No left rail: level lists (connections / feeds) are tabs so the layout never
 * shifts when you open a connection.
 */
export function ConnectorPageShell({
	header,
	tabs,
	value,
	onValueChange,
	children,
}: {
	header: ReactNode;
	tabs: { value: string; label: string; disabled?: boolean }[];
	value: string;
	onValueChange: (value: string) => void;
	children: ReactNode;
}) {
	return (
		<div className="flex min-h-0 min-w-0 flex-1 flex-col">
			<Tabs
				value={value}
				onValueChange={onValueChange}
				className="flex min-h-0 min-w-0 w-full max-w-3xl flex-1 flex-col"
			>
				<div className="sticky top-0 z-10 space-y-4 bg-background pb-1">
					{header}
					<TabsList className="gap-5">
						{tabs.map((tab) => (
							<TabsTrigger
								key={tab.value}
								value={tab.value}
								disabled={tab.disabled}
								className="px-0.5"
							>
								{tab.label}
							</TabsTrigger>
						))}
					</TabsList>
				</div>
				<div className="mt-4 min-w-0 flex-1 space-y-4">{children}</div>
			</Tabs>
		</div>
	);
}

