/**
 * Tab bars for connector vs connection pages.
 *
 * Same four slots / same width so the layout does not shift when you descend:
 *   Overview | (Connections | Feeds) | Actions | Settings
 *
 * The middle slot is level-scoped:
 *   - connector page → Connections
 *   - connection page → Feeds (channels for chat)
 */
export const CONNECTOR_PAGE_TABS = [
	{ value: "overview", label: "Overview" },
	{ value: "connections", label: "Connections" },
	{ value: "actions", label: "Actions" },
	{ value: "settings", label: "Settings" },
] as const;

export const CONNECTION_PAGE_TABS = [
	{ value: "overview", label: "Overview" },
	{ value: "feeds", label: "Feeds" },
	{ value: "actions", label: "Actions" },
	{ value: "settings", label: "Settings" },
] as const;

/** Union of every tab value that can appear in `?tab=`. */
export type ConnectorTabValue =
	| (typeof CONNECTOR_PAGE_TABS)[number]["value"]
	| (typeof CONNECTION_PAGE_TABS)[number]["value"];

const ALL_TAB_VALUES = new Set<string>([
	...CONNECTOR_PAGE_TABS.map((t) => t.value),
	...CONNECTION_PAGE_TABS.map((t) => t.value),
]);

/**
 * Parse `?tab=`. Unknown values fall back to overview so stale bookmarks still
 * land on a real tab.
 */
export function parseConnectorTab(value: unknown): ConnectorTabValue {
	if (typeof value === "string" && ALL_TAB_VALUES.has(value)) {
		return value as ConnectorTabValue;
	}
	return "overview";
}

/**
 * Pick a tab that is enabled for this page. `tabs` is the page's ordered list
 * so fallback walks the visible bar, not a global union.
 */
export function resolveEnabledConnectorTab(
	requested: ConnectorTabValue,
	enabled: Partial<Record<ConnectorTabValue, boolean>>,
	tabs: readonly { value: ConnectorTabValue }[] = CONNECTOR_PAGE_TABS,
): ConnectorTabValue {
	if (enabled[requested] !== false && tabs.some((t) => t.value === requested)) {
		return requested;
	}
	for (const tab of tabs) {
		if (enabled[tab.value] !== false) return tab.value;
	}
	return "settings";
}

/** @deprecated Use CONNECTOR_PAGE_TABS or CONNECTION_PAGE_TABS. */
export const CONNECTOR_TABS = CONNECTOR_PAGE_TABS;

