import { describe, expect, it } from "vitest";
import {
	CONNECTION_PAGE_TABS,
	CONNECTOR_PAGE_TABS,
	parseConnectorTab,
	resolveEnabledConnectorTab,
} from "@/components/connectors/connector-tabs";

describe("page tabs", () => {
	it("share four slots so layout width is stable", () => {
		expect(CONNECTOR_PAGE_TABS).toHaveLength(4);
		expect(CONNECTION_PAGE_TABS).toHaveLength(4);
		expect(CONNECTOR_PAGE_TABS.map((t) => t.value)).toEqual([
			"overview",
			"connections",
			"actions",
			"settings",
		]);
		expect(CONNECTION_PAGE_TABS.map((t) => t.value)).toEqual([
			"overview",
			"feeds",
			"actions",
			"settings",
		]);
	});
});

describe("parseConnectorTab", () => {
	it("accepts connector and connection tab values", () => {
		expect(parseConnectorTab("connections")).toBe("connections");
		expect(parseConnectorTab("feeds")).toBe("feeds");
		expect(parseConnectorTab("actions")).toBe("actions");
		expect(parseConnectorTab("settings")).toBe("settings");
		expect(parseConnectorTab("overview")).toBe("overview");
	});

	it("maps unknown values to overview", () => {
		expect(parseConnectorTab("nope")).toBe("overview");
		expect(parseConnectorTab(undefined)).toBe("overview");
	});
});

describe("resolveEnabledConnectorTab", () => {
	it("keeps the requested tab when it is enabled", () => {
		expect(
			resolveEnabledConnectorTab(
				"connections",
				{ overview: true, connections: true, actions: true, settings: true },
				CONNECTOR_PAGE_TABS,
			),
		).toBe("connections");
	});

	it("falls through within the page's tab list", () => {
		expect(
			resolveEnabledConnectorTab(
				"actions",
				{ overview: true, connections: true, actions: false, settings: true },
				CONNECTOR_PAGE_TABS,
			),
		).toBe("overview");
	});

	it("does not land on a tab that is not on this page", () => {
		// Requesting "connections" on a connection page → first enabled connection tab.
		expect(
			resolveEnabledConnectorTab(
				"connections",
				{ overview: true, feeds: true, actions: true, settings: true },
				CONNECTION_PAGE_TABS,
			),
		).toBe("overview");
	});
});

