import type { ReactNode } from "react";

/**
 * Connector / connection page chrome — a single centred column, the same width
 * at every depth, matching the agent pages (`mx-auto w-full max-w-3xl`).
 *
 *   header
 *   body (sections)
 *
 * There is no tab bar. Every page under `connectors/` used to carry one, and
 * every one of them had panels that were empty for some instances: a runtime's
 * Connections tab said runtimes have no connections, a provider's Actions tab
 * said providers have no actions, a chat connection's Overview said chat does
 * not sync. The two bars were also kept the same width — the middle slot
 * swapping label between Connections / Feeds / Channels — so descending a level
 * did not resize them, which is not something peer alternatives need.
 * Content is laid out with `PageSection` instead; a section that has nothing to
 * say is simply not rendered.
 */
export function ConnectorPageShell({
	header,
	children,
}: {
	header: ReactNode;
	children: ReactNode;
}) {
	return (
		<div className="mx-auto flex min-h-0 w-full min-w-0 max-w-3xl flex-1 flex-col">
			<div className="sticky top-0 z-10 space-y-4 bg-background pb-1">
				{header}
			</div>
			<div className="mt-4 min-w-0 flex-1 space-y-7">{children}</div>
		</div>
	);
}

