import type { ReactNode } from "react";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";

/**
 * Connector / connection page chrome — single centred column, same width at
 * every depth, matching the agent pages (`mx-auto w-full max-w-3xl`).
 *
 *   header
 *   tabs (optional)
 *   body
 *
 * `tabs` is omitted on the connection page, which lays its content out as
 * sections instead — see `PageSection`. It stays on the connector page, where
 * the panels really are peer alternatives.
 */
export function ConnectorPageShell({
	header,
	tabs,
	value,
	onValueChange,
	children,
}: {
	header: ReactNode;
	tabs?: { value: string; label: string; disabled?: boolean }[];
	value?: string;
	onValueChange?: (value: string) => void;
	children: ReactNode;
}) {
	if (!tabs) {
		return (
			<div className="mx-auto flex min-h-0 w-full min-w-0 max-w-3xl flex-1 flex-col">
				<div className="sticky top-0 z-10 space-y-4 bg-background pb-1">
					{header}
				</div>
				<div className="mt-4 min-w-0 flex-1 space-y-7">{children}</div>
			</div>
		);
	}

	return (
		<div className="flex min-h-0 min-w-0 flex-1 flex-col">
			<Tabs
				value={value}
				onValueChange={onValueChange}
				className="mx-auto flex min-h-0 w-full min-w-0 max-w-3xl flex-1 flex-col"
			>
				<div className="sticky top-0 z-10 space-y-4 bg-background pb-1">
					{header}
					<TabsList className="gap-5">
						{tabs.map((tab) => (
							<TabsTrigger
								key={tab.value}
								value={tab.value}
								disabled={tab.disabled}
								className="px-0.5"
							>
								{tab.label}
							</TabsTrigger>
						))}
					</TabsList>
				</div>
				<div className="mt-4 min-w-0 flex-1 space-y-4">{children}</div>
			</Tabs>
		</div>
	);
}

