import { Link } from "@tanstack/react-router";
import { ExternalLink } from "lucide-react";
import type { ReactNode } from "react";
import { Badge } from "@/components/ui/badge";
import {
	Popover,
	PopoverContent,
	PopoverTrigger,
} from "@/components/ui/popover";
import type { ConnectorDefinitionItem } from "@/lib/api/connections";

/**
 * Where a connection's behaviour comes from, in one line.
 *
 * A connection does not define how it works — the connector definition does,
 * and that definition has a version, an origin, and sometimes a URI it was
 * generated from. All of it is already on `ConnectorDefinitionItem`.
 *
 * The rest of the definition metadata — key, source, platforms, capability,
 * scopes — is real but it is reference material, not page content. It used to
 * be an "About" block of six-plus monospace rows sitting above the setup forms,
 * which read as though the page were about the definition rather than about
 * connecting. It now hangs off the version chip, which is the thing you are
 * holding when you want it: something changed, what changed, where did it come
 * from.
 */
export function ConnectorProvenance({
	connectorDef,
	connectorKey,
	ownerSlug,
	/** On the connector's own page there is nowhere to link to. */
	linkToConnector = true,
}: {
	connectorDef: ConnectorDefinitionItem | undefined;
	connectorKey: string;
	ownerSlug: string;
	linkToConnector?: boolean;
}) {
	if (!connectorDef) return null;

	const isOrgBuilt = connectorDef.catalog_origin === "org";

	return (
		<div className="flex flex-wrap items-center gap-x-2 gap-y-1.5 text-[11.5px] text-muted-foreground">
			<span>Runs on</span>
			{linkToConnector ? (
				<Link
					to="/$owner/connectors/$connectorKey"
					params={{ owner: ownerSlug, connectorKey }}
					className="underline underline-offset-2 hover:text-foreground"
				>
					{connectorDef.name}
				</Link>
			) : (
				<span className="text-foreground">{connectorDef.name}</span>
			)}

			<Popover>
				<PopoverTrigger className="rounded border px-1.5 py-0.5 transition-colors hover:border-muted-foreground hover:text-foreground">
					v{connectorDef.version || "unknown"}
				</PopoverTrigger>
				<PopoverContent align="start" className="w-80 p-0">
					<ConnectorDefinitionDetails
						connectorDef={connectorDef}
						ownerSlug={ownerSlug}
					/>
				</PopoverContent>
			</Popover>

			<span
				className={
					isOrgBuilt
						? "rounded border border-amber-500/45 px-1.5 py-0.5 text-amber-600 dark:text-amber-500"
						: "rounded border px-1.5 py-0.5"
				}
			>
				{isOrgBuilt ? "built in this workspace" : "Lobu catalog"}
			</span>
		</div>
	);
}

/** The full definition record, behind the version chip. */
function ConnectorDefinitionDetails({
	connectorDef,
	ownerSlug,
}: {
	connectorDef: ConnectorDefinitionItem;
	ownerSlug: string;
}) {
	const platforms = connectorDef.runtime?.platforms ?? [];
	const scopes = connectorDef.runtime?.scopes ?? [];
	const sourceUri = connectorDef.source_uri?.trim() || null;
	const sourceIsHttp =
		!!sourceUri &&
		(sourceUri.startsWith("http://") || sourceUri.startsWith("https://"));

	const rows: Array<{ label: string; value: ReactNode }> = [
		{
			label: "Key",
			value: <span className="font-mono">{connectorDef.key}</span>,
		},
		{
			label: "Version",
			value: (
				<span className="font-mono">
					{connectorDef.version ? `v${connectorDef.version}` : "unknown"}
				</span>
			),
		},
	];

	if (sourceUri) {
		rows.push({
			label: "Source",
			value: sourceIsHttp ? (
				<a
					href={sourceUri}
					target="_blank"
					rel="noreferrer"
					className="inline-flex max-w-full items-start gap-1 break-all font-mono text-primary hover:underline"
				>
					{sourceUri}
					<ExternalLink className="mt-0.5 h-3 w-3 shrink-0" />
				</a>
			) : (
				<span className="break-all font-mono">{sourceUri}</span>
			),
		});
	}

	if (platforms.length > 0) {
		rows.push({
			label: "Platforms",
			value: (
				<span className="flex flex-wrap gap-1">
					{platforms.map((p) => (
						<Badge
							key={p}
							variant="secondary"
							className="h-4 px-1 py-0 font-mono text-[10px]"
						>
							{p}
						</Badge>
					))}
				</span>
			),
		});
	}

	if (connectorDef.required_capability) {
		rows.push({
			label: "Capability",
			value: (
				<span className="font-mono">{connectorDef.required_capability}</span>
			),
		});
	}

	if (scopes.length > 0) {
		rows.push({
			label: "Scopes",
			value: (
				<span className="flex flex-wrap gap-1">
					{scopes.map((scope) => (
						<Badge
							key={scope}
							variant="secondary"
							className="h-4 px-1 py-0 font-mono text-[10px]"
						>
							{scope}
						</Badge>
					))}
				</span>
			),
		});
	}

	return (
		<div className="text-xs">
			<dl className="divide-y">
				{rows.map((row) => (
					<div key={row.label} className="flex gap-3 px-3 py-2">
						<dt className="w-20 shrink-0 text-muted-foreground">{row.label}</dt>
						<dd className="min-w-0 flex-1">{row.value}</dd>
					</div>
				))}
			</dl>
			{platforms.length > 0 ? (
				<div className="border-t px-3 py-2 text-muted-foreground">
					Runs on a linked device.{" "}
					<Link
						to="/$owner/connectors/runtime"
						params={{ owner: ownerSlug }}
						search={{ provider: undefined }}
						className="text-primary hover:underline"
					>
						View devices
					</Link>
				</div>
			) : null}
		</div>
	);
}

