import { Link } from "@tanstack/react-router";
import type { ConnectorDefinitionItem } from "@/lib/api/connections";

/**
 * Where a connection's behaviour comes from.
 *
 * A connection does not define how it works — the connector definition does,
 * and that definition has a version, an origin, and sometimes a URI it was
 * generated from. All of it is already on `ConnectorDefinitionItem` and none of
 * it was rendered, so when a sync starts failing after a connector update there
 * was nothing on the page to point at. `catalog_origin: "org"` matters most: a
 * connector built in the workspace is somebody here's responsibility rather
 * than Lobu's, and the person debugging it should not have to find that out.
 */
export function ConnectorProvenance({
	connectorDef,
	connectorKey,
	ownerSlug,
}: {
	connectorDef: ConnectorDefinitionItem | undefined;
	connectorKey: string;
	ownerSlug: string;
}) {
	if (!connectorDef) return null;

	const isOrgBuilt = connectorDef.catalog_origin === "org";
	const platforms = connectorDef.runtime?.platforms;

	return (
		<div className="flex flex-wrap items-center gap-x-2 gap-y-1.5 text-[11.5px] text-muted-foreground">
			<span>Runs on</span>
			<Link
				to="/$owner/connectors/$connectorKey"
				params={{ owner: ownerSlug, connectorKey }}
				className="underline underline-offset-2 hover:text-foreground"
			>
				{connectorDef.name}
			</Link>
			<span className="rounded border px-1.5 py-0.5">
				v{connectorDef.version}
			</span>
			<span
				className={
					isOrgBuilt
						? "rounded border border-amber-500/45 px-1.5 py-0.5 text-amber-600 dark:text-amber-500"
						: "rounded border px-1.5 py-0.5"
				}
			>
				{isOrgBuilt ? "built in this workspace" : "Lobu catalog"}
			</span>
			{connectorDef.source_uri ? (
				<>
					<span>generated from</span>
					<code className="font-mono text-[11px]">
						{connectorDef.source_uri}
					</code>
				</>
			) : null}
			{connectorDef.required_capability ? (
				<span className="rounded border px-1.5 py-0.5">
					needs {connectorDef.required_capability}
				</span>
			) : null}
			{platforms?.length ? <span>runs on {platforms.join(", ")}</span> : null}
		</div>
	);
}

