				</span>
			))}
		</nav>
	);
}

/**
 * Connector / connection / feed header.
 *
 *   [icon]  Connectors › Discord  v1.0.0     ← icon + title row vertically centered
 *   description under the whole block (starts under the icon, full width)
 */
export function DetailHeader({
	breadcrumb,
	icon,
	title,
	badge,
	status,
	meta,
	caption,
	captionTone = "muted",
}: {
	breadcrumb?: ReactNode;
	icon?: ReactNode;
	title: ReactNode;
	badge?: ReactNode;
	status?: ReactNode;
	meta?: ReactNode;
	caption?: ReactNode;
	captionTone?: "muted" | "error";
}) {
	const titleRow = (
		<div className="flex min-w-0 flex-1 flex-wrap items-center justify-between gap-x-3 gap-y-1">
			<div className="flex min-w-0 flex-wrap items-center gap-x-2.5 gap-y-1">
				{breadcrumb}
				{typeof title === "string" ? (
					<h1 className="text-2xl font-semibold leading-none tracking-tight">
						{title}
					</h1>
				) : (
					title
				)}
				{badge}
				{status}
			</div>
			{meta ? (
				<div className="flex flex-wrap items-center gap-x-4 gap-y-1 text-xs text-muted-foreground">
					{meta}
				</div>
			) : null}
		</div>
	);

	const captionEl = caption ? (
		<p
			className={cn(
				"max-w-2xl text-base leading-relaxed",
				captionTone === "error"
					? "text-destructive"
					: "text-muted-foreground",
			)}
		>
			{caption}
		</p>
	) : null;

	if (icon) {
		return (
			<div className="flex flex-col gap-2.5">
				{/* Icon + title on one row, vertically centered */}
				<div className="flex min-w-0 items-center gap-3">
					<div className="shrink-0">{icon}</div>
					{titleRow}
				</div>
				{/* Description under the icon (full block width) */}
				{captionEl}
			</div>
		);
	}

	return (
		<div className="flex flex-col gap-2.5">
			{titleRow}
			{captionEl}
		</div>
	);
}

