function MainConnectorSurface({
	connector,
	organizationId,
	ownerSlug,
	connectorKey,
	connections,
	isLoading,
	refetchConnections,
}: {
	connector: ConnectorDefinitionItem;
	organizationId: string;
	ownerSlug: string;
	connectorKey: string;
	connections: ConnectionItem[];
	isLoading: boolean;
	refetchConnections: () => void;
}) {
	const methods = getSelectableMethods(connector.auth_schema);
	const oauthMethod = methods.find((m) => m.type === "oauth") as
			appProfiles.find(
				(p) => p.is_default_for_connector && p.status === "active",
			) ??
			appProfiles.find((p) => p.status === "active") ??
			appProfiles[0] ??
			null;
		return (
			<OAuthAccountsSection
				connector={connector}
				oauthMethod={oauthMethod}
