				connections={connections}
				isLoading={isLoading}
				refetchProfiles={refetchProfiles}
				refetchConnections={refetchConnections}
			/>
		);
	}

	return (
		<ConnectionsForConnector
			connector={connector}
			ownerSlug={ownerSlug}
			connectorKey={connectorKey}
			connections={connections}
			isLoading={isLoading}
		/>
	);
}

