 * Connector-level action policy. Sets `default_connection_config.action_modes`
 * on the connector definition — the default every connection of this connector
 * inherits unless it overrides in its own config. Only rendered when the
 * connector exposes operations and the viewer is an admin.
 */
function ConnectorActionsSection({
	connector,
	organizationId,
}: {
	connector: ConnectorDefinitionItem;
	organizationId: string;
}) {
	const { isAdmin } = useMembers(organizationId);
	const { data: operations = [] } = useConnectorOperations(connector.key);
	const updateDefaultConfig = useUpdateConnectorDefaultConfig();

	const savedModes = useMemo(
		() => readActionModes(connector.default_connection_config),
		[connector.default_connection_config],
	);
	const [modes, setModes] = useState<Record<string, ActionMode>>(savedModes);
	const [dirty, setDirty] = useState(false);

	if (!isAdmin || operations.length === 0) return null;

	const handleChange = (next: Record<string, ActionMode>) => {
		setModes(next);
		setDirty(true);
	};

	const handleSave = () => {
		const nextConfig = {
			...(connector.default_connection_config ?? {}),
			action_modes: modes,
		};
		updateDefaultConfig.mutate(
			{ connector_key: connector.key, default_connection_config: nextConfig },
			{ onSuccess: () => setDirty(false) },
		);
	};

	return (
		<PageSection title="Action policy">
			<p className="mb-3 text-xs text-muted-foreground">
