// Actions Editor — tri-state per action (disabled / approval / auto)
// ============================================================

interface ActionsEditorOp {
	operation_key: string;
	name?: string;
	description?: string;
	requires_approval?: boolean;
}

/**
 * Single editor used in both install (create mode) and the manage-actions
 * surfaces from edit mode. When `onChange` is omitted the editor renders
 * read-only: a label per op showing its effective mode.
 */
export function ActionsEditor({
	operations,
	modes,
	onChange,
}: {
	operations: ActionsEditorOp[];
	modes: Record<string, ActionMode>;
	onChange?: (next: Record<string, ActionMode>) => void;
}) {
	if (operations.length === 0) return null;
	const interactive = !!onChange;

	const setMode = (op: ActionsEditorOp, mode: ActionMode) => {
		if (!onChange) return;
		const fallback = defaultActionMode(op);
		const next = { ...modes };
		// Don't persist an entry that matches the connector default — keeps
		// configs small and makes "what did the user explicitly choose?"
		// easy to read.
		if (mode === fallback) {
			delete next[op.operation_key];
		} else {
			next[op.operation_key] = mode;
		}
		onChange(next);
	};

	return (
		<div className="space-y-2">
			<p className="text-xs font-medium text-muted-foreground uppercase tracking-wider">
				Actions
			</p>
			<div className="space-y-2">
				{operations.map((op) => {
					const mode = resolveActionMode(op, modes);
					return (
						<div key={op.operation_key} className="space-y-1">
							<div>
								<span className="text-sm">{op.name ?? op.operation_key}</span>
								{op.description && (
									<p className="text-xs text-muted-foreground">
										{op.description}
									</p>
								)}
							</div>
							{interactive ? (
								<SegmentedActionMode
									value={mode}
									onChange={(next) => setMode(op, next)}
									aria-label={`Mode for ${op.name ?? op.operation_key}`}
								/>
							) : (
								<p className="text-xs text-muted-foreground">
									{ACTION_MODE_LABELS[mode]}
								</p>
							)}
						</div>
					);
				})}
			</div>
		</div>
	);
}

function SegmentedActionMode({
	value,
	onChange,
	"aria-label": ariaLabel,
}: {
	value: ActionMode;
	onChange: (next: ActionMode) => void;
	"aria-label"?: string;
}) {
	return (
		<div
			role="radiogroup"
			aria-label={ariaLabel}
			className="inline-flex rounded-lg border bg-background p-0.5"
		>
			{ACTION_MODE_ORDER.map((mode) => {
				const selected = mode === value;
				return (
					<button
						key={mode}
						type="button"
						role="radio"
						aria-checked={selected}
						onClick={() => onChange(mode)}
						className={`rounded-md px-2.5 py-1 text-xs transition-colors ${
							selected
								? "bg-muted text-foreground"
								: "text-muted-foreground hover:text-foreground"
						}`}
					>
						{ACTION_MODE_LABELS[mode]}
					</button>

