export function ConnectionActionsSection({
	connection,
}: {
	connection: ConnectionItem;
}) {
	// useConnectorOperations returns every op the connector defines, including
	// ones the user has set to `disabled`. The connection-scoped list would
	// hide them, which would leave no path to re-enable from this surface.
	const { data: operations = [] } = useConnectorOperations(
		connection.connector_key,
	);
	const updateConnection = useUpdateConnection();
	const [editing, setEditing] = useState(false);
	const persistedModes = readActionModes(connection.config);
	const [draft, setDraft] =
		useState<Record<string, ActionMode>>(persistedModes);
	// Reset the draft each time the editor opens or the connection swaps, so
	// stale tweaks don't carry over. Intentionally keyed on open/swap only —
	// depending on `persistedModes` would clobber in-progress edits whenever the
	// connection refetches.
	// biome-ignore lint/correctness/useExhaustiveDependencies: reset only on open/connection-swap, not on every persistedModes change
	useEffect(() => {
		if (editing) setDraft(persistedModes);
	}, [editing, connection.id]);

	if (operations.length === 0) return null;

	const handleSave = () => {
		const nextConfig = {
			...(connection.config ?? {}),
			action_modes: draft,
		} as Record<string, unknown>;
		updateConnection.mutate(
			{ connection_id: connection.id, config: nextConfig },
			{ onSuccess: () => setEditing(false) },
		);
	};

	return (
		<div className="space-y-2">
			<div className="flex items-center justify-between gap-3">
				<div>
					<Label>Actions</Label>
					<p className="text-xs text-muted-foreground">
						Inherits the connector's default policy. Override any action for
						this connection only.
					</p>
				</div>
				{!editing ? (
					<Button variant="outline" size="sm" onClick={() => setEditing(true)}>
						Override actions
					</Button>
				) : null}
			</div>
			{!editing ? (
				<div className={cn(FILLED_BOX, "p-4")}>
					<ActionModesSummary operations={operations} modes={persistedModes} />
				</div>
			) : (
				<div className={FILLED_BOX}>
					<div className="border-b px-4 py-3">
						<p className="text-sm font-medium">Manage actions</p>
						<p className="mt-0.5 text-xs text-muted-foreground">
							Choose how the agent treats each action: disabled hides it,
							requires approval prompts you first, auto-approve runs without
							confirmation.
						</p>
					</div>
					<div className="px-4 py-3">
						<ActionsEditor
							operations={operations}
							modes={draft}
							onChange={setDraft}
						/>
					</div>
					<div className="flex justify-end gap-2 border-t px-4 py-3">
						<Button
							variant="outline"
							size="sm"
							onClick={() => setEditing(false)}
						>
							Cancel
						</Button>
						<Button
							size="sm"
							onClick={handleSave}
							disabled={updateConnection.isPending}
						>
							{updateConnection.isPending ? "Saving..." : "Save"}
						</Button>
					</div>
				</div>
			)}
		</div>
	);
}

