function ConnectionActionsSection({
	connection,
}: {
	connection: ConnectionItem;
}) {
	// useConnectorOperations returns every op the connector defines, including
	// ones the user has set to `disabled`. The connection-scoped list would
	// hide them, leaving no path to re-enable from this surface. We also drop
	// the kind === 'write' filter — `disabled` is meaningful for reads too
	// (the agent must not call them at all).
	const { data: operations = [] } = useConnectorOperations(
		connection.connector_key,
	);
	const updateConnection = useUpdateConnection();
	const persistedSnapshot = useMemo(() => {
		const modes = readActionModes(connection.config);
		return {
			connectionId: connection.id,
			key: JSON.stringify(modes),
			modes,
		};
	}, [connection.config, connection.id]);
	// Local draft so toggling multiple ops doesn't race in-flight mutations —
	// each click on immediate-save would read stale `connection.config` until
	// the previous mutation invalidated the query.
	const [draft, setDraft] = useState<Record<string, ActionMode>>(
		persistedSnapshot.modes,
	);
	// Resync the draft whenever the server-side mode set changes (after a
	// successful save, when the connection is swapped, etc.).
	useEffect(() => {
		setDraft(persistedSnapshot.modes);
	}, [persistedSnapshot]);
	const persistedKey = persistedSnapshot.key;

	if (operations.length === 0) return null;

	const isDirty = JSON.stringify(draft) !== persistedKey;

	const handleSave = () => {
		const nextConfig = {
			...(connection.config ?? {}),
			action_modes: draft,
		} as Record<string, unknown>;
		updateConnection.mutate({
			connection_id: connection.id,
			config: nextConfig,
		});
	};

	return (
		<div className="space-y-2">
			<ActionsEditor
