import { parseAppHref } from "@/lib/activity-links";

/**
 * Resolve a clicked activity/notification href into a structured peek
 * destination so the pane can mount the right shared content component. The
 * dedicated pages parse the same strings from their own URLs.
 *
 * Peekable destinations render their dedicated-page content component inline in
 * the pane (behavior runs, memory events/approvals). Connector detail is a full
 * management surface and doesn't fit a 460px pane, so it navigates normally
 * (the caller falls back to navigate() when this returns null).
 */
export type PeekDestination =
	| {
			kind: "behavior";
			owner: string;
			agentId: string;
			watcherId: string;
			view?: "activity" | "definition";
			runId?: number;
	  }
	| {
			kind: "memory";
			owner: string;
			runId?: number;
	  };

const SEG = "[^/]+";

const BEHAVIOR_RE = new RegExp(
	`^/(${SEG})/agents/(${SEG})/behaviors/(${SEG})/?$`,
);

// Run permalinks live on /activity now; stored notification hrefs from before
// the Activity/Memory split still say /memory, so both shapes stay peekable.
const RUN_STREAM_RE = new RegExp(`^/(${SEG})/(?:activity|memory)/?$`);

export function parsePeekHref(href: string): PeekDestination | null {
	const { pathname, search } = parseAppHref(href);

	const m = pathname.match(BEHAVIOR_RE);
	if (m) {
		const [, owner, agentId, watcherId] = m;
		const view =
			search?.view === "activity" || search?.view === "definition"
				? search.view
				: undefined;
		const runId = parseRunId(search?.run_id);
		return { kind: "behavior", owner, agentId, watcherId, view, runId };
	}

