		const rawRunIds = search?.run_ids;
		const ids =
			rawRunIds != null && rawRunIds !== "" ? rawRunIds.split(",") : [];
		if (ids.length !== 1) return null;
		const runId = parseRunId(ids[0]);
		if (runId == null) return null;
		return { kind: "memory", owner, runId };
	}

	return null;
