import { describe, expect, it } from "vitest";
import { resolveActionMode } from "@/components/entity-tabs/connections-tab/connector-panels";

/**
 * The default mode is not `requires_approval ? approval : auto`. A write with
 * only `annotations.destructiveHint` also defaults to approval, and a read
 * always defaults to auto. Re-deriving this at a call site understates the
 * policy — the row says Auto-approve while the backend asks first.
 */
describe("resolveActionMode defaults", () => {
	it("asks first for a destructive write with no requires_approval", () => {
		expect(
			resolveActionMode(
				{
					operation_key: "delete_issue",
					kind: "write",
					annotations: { destructiveHint: true },
				},
				{},
			),
		).toBe("approval");
	});

	it("leaves reads open", () => {
		expect(
			resolveActionMode({ operation_key: "list_issues", kind: "read" }, {}),
		).toBe("auto");
	});

	it("asks first when requires_approval is set", () => {
		expect(
			resolveActionMode(
				{ operation_key: "create_issue", kind: "write", requires_approval: true },
				{},
			),
		).toBe("approval");
	});

	it("an explicit configured mode wins over the default", () => {
		expect(
			resolveActionMode(
				{
					operation_key: "delete_issue",
					kind: "write",
					annotations: { destructiveHint: true },
				},
				{ delete_issue: "auto" },
			),
		).toBe("auto");
	});
});
EOF
