import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import {
  createMemoryHistory,
  createRootRoute,
  createRoute,
  createRouter,
  Outlet,
  RouterProvider,
} from "@tanstack/react-router";
import { fireEvent, render, screen, waitFor } from "@testing-library/react";
import type { ReactNode } from "react";
import { afterEach, describe, expect, it, vi } from "vitest";
import type { ContentItem } from "@/lib/api";
import { EventCard } from "./event-card";

/**
 * Interaction contract for opening an event in the peek pane.
 *
 * Two bugs shipped here and neither was visible to a typecheck:
 *
 *  1. The card built `?run_id=`, but `parsePeekHref` reads `run_ids` (plural).
 *     `canPeek` was therefore always false — no card ever got a handler, the
 *     peek never opened, and the copy-permalink control it replaced was already
 *     gone. A one-character difference inside a template literal.
 *  2. The card carries `role="button"`, and it wraps its own controls. A bare
 *     onClick on the container fires for those too, so clicking a link or a
 *     disclosure inside the card also opened the pane.
 *
 * Both are asserted below against the real `parsePeekHref`, which is the thing
 * that decides reachability.
 */

const openSpy = vi.fn();

vi.mock("@/components/peek/notification-peek-context", () => ({
  useNotificationPeek: () => ({ item: null, open: openSpy, close: vi.fn() }),
}));

vi.mock("@/hooks/use-org-context", () => ({
  useOrgContext: () => ({ currentOwner: "acme" }),
}));

function TestProvider({ children }: { children: ReactNode }) {
  const queryClient = new QueryClient({
    defaultOptions: { queries: { retry: false }, mutations: { retry: false } },
  });
  const rootRoute = createRootRoute({ component: () => <Outlet /> });
  const indexRoute = createRoute({
    getParentRoute: () => rootRoute,
    path: "/",
    component: () => <>{children}</>,
  });
  const router = createRouter({
    routeTree: rootRoute.addChildren([indexRoute]),
    history: createMemoryHistory({ initialEntries: ["/"] }),
  });
  return (
    <QueryClientProvider client={queryClient}>
      {/* biome-ignore lint/suspicious/noExplicitAny: test-local router instance */}
      <RouterProvider router={router as any} />
    </QueryClientProvider>
  );
}

async function renderCard(overrides: Partial<ContentItem> = {}) {
  const content = {
    id: 100,
    title: "Ran send_email",
    text_content: "Sent a message to dara@acme.com",
    semantic_type: "operation",
    origin_type: "tool_invocation",
    source_url: "https://mail.google.com/mail/u/0/#sent/abc",
    metadata: {},
    ...overrides,
  } as unknown as ContentItem;
  const result = render(<EventCard content={content} />, {
    wrapper: TestProvider,
  });
  await waitFor(() =>
    expect(result.container.textContent ?? "").not.toEqual("")
  );
  return result;
}

describe("event card → peek", () => {
  afterEach(() => {
    openSpy.mockReset();
    vi.restoreAllMocks();
  });

  it("opens the peek with the plural run_ids param the parser accepts", async () => {
    await renderCard({ run_id: 42 } as Partial<ContentItem>);

    const card = screen.getByRole("button", { name: /Ran send_email/ });
    fireEvent.click(card);

    expect(openSpy).toHaveBeenCalledTimes(1);
    // `run_ids`, not `run_id`. The singular form parses to null, which silently
    // makes the whole feature unreachable.
    expect(openSpy.mock.calls[0][0]).toMatchObject({
      href: "/acme/activity?run_ids=42",
      runId: 42,
    });
  });

  it("is inert for an event with no run, rather than a button that does nothing", async () => {
    const { container } = await renderCard();

    expect(
      container.querySelector('[role="button"]')?.textContent ?? ""
    ).not.toContain("Ran send_email");
    expect(openSpy).not.toHaveBeenCalled();
  });

  it("ignores clicks that came from a control inside the card", async () => {
    await renderCard({ run_id: 42 } as Partial<ContentItem>);

    // "View original" is a real anchor nested inside the clickable card.
    const nested = screen.getByRole("link");
    fireEvent.click(nested);

    expect(openSpy).not.toHaveBeenCalled();
  });

  it("opens on Enter from the card body", async () => {
    await renderCard({ run_id: 42 } as Partial<ContentItem>);

    const card = screen.getByRole("button", { name: /Ran send_email/ });
    fireEvent.keyDown(card, { key: "Enter" });

    expect(openSpy).toHaveBeenCalledTimes(1);
  });
});

